import{_ as t,o as a,c as r,an as o}from"./chunks/framework.DBFeC3Rc.js";const f=JSON.parse('{"title":"Validation matrix","description":"","frontmatter":{},"headers":[],"relativePath":"users/benchmarks/validation-matrix.md","filePath":"users/benchmarks/validation-matrix.md","lastUpdated":null}'),n={name:"users/benchmarks/validation-matrix.md"};function i(s,e,l,d,c,h){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="Validation-matrix" tabindex="-1">Validation matrix <a class="header-anchor" href="#Validation-matrix" aria-label="Permalink to &quot;Validation matrix {#Validation-matrix}&quot;">​</a></h1><p>The single summary of where each public Kraken module stands against an external reference. Every numeric cell is the headline metric of the linked benchmark page — no value is reproduced here that is not on one of those pages. Each row gives the <strong>published/analytical reference</strong>, an <strong>independent other-solver comparison</strong> where one exists, and the <strong>tolerance met</strong> against the mandate §3 acceptance bar.</p><p>Where RheoTool covers a case it is the literal reference solver; where it does not, §3&#39;s escape clause anchors the row to the canonical published data set (Ghia 1982 for the cavity, de Vahl Davis 1983 for thermal, Clift et al. 1978 for sphere drag), each with an independent OpenFOAM cross-check where available.</p><h2 id="Matrix" tabindex="-1">Matrix <a class="header-anchor" href="#Matrix" aria-label="Permalink to &quot;Matrix {#Matrix}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Module</th><th style="text-align:right;">Analytical / published reference</th><th style="text-align:right;">Other-solver comparison</th><th style="text-align:right;">Tolerance target (§3)</th><th style="text-align:right;">Result actually met</th><th style="text-align:right;">Artifact</th></tr></thead><tbody><tr><td style="text-align:right;"><strong>Newtonian — lid-driven cavity</strong> (D2Q9 BGK)</td><td style="text-align:right;">Ghia, Ghia &amp; Shin (1982), centreline <code>u</code>/<code>v</code></td><td style="text-align:right;">OpenFOAM <code>icoFoam</code> (FVM); independently clears &lt; 1 % vs Ghia (0.49 / 0.23 / 0.46 %)</td><td style="text-align:right;">rel-L2 &lt; 1 % on u-centreline (strict); ≤ 5 % local field</td><td style="text-align:right;"><strong>PASS</strong> — rel-L2 <strong>0.47 % / 0.41 % / 1.05 %</strong> at Re = 100 / 400 / 1000 (Re = 1000 marginal, abs-RMS 0.43 %)</td><td style="text-align:right;"><a href="./cartesian-cavity">Cartesian cavity</a>; literal both-solver bundle <code>benchmarks/results/rheotool_compare/newtonian/</code> (<code>.krk</code> + CSVs + <code>plot.py</code> + figure + README)</td></tr><tr><td style="text-align:right;"><strong>Thermal — natural convection</strong> (double-distribution D2Q9)</td><td style="text-align:right;">de Vahl Davis (1983), <code>Nu</code> at Pr = 0.71</td><td style="text-align:right;">OpenFOAM <code>buoyantBoussinesqSimpleFoam</code> (FVM SIMPLE); corroborates dVD at Ra = 10³ (−0.56 %) and 10⁵ (−0.60 %)</td><td style="text-align:right;">&lt; 1 % on Nu; &lt; 2 % on velocity extrema</td><td style="text-align:right;"><strong>PASS</strong> — Nu err <strong>+0.79 % / +0.93 % / +0.79 %</strong> at Ra = 10³ / 10⁴ / 10⁵; velocity extrema all &lt; 1 %</td><td style="text-align:right;"><a href="./thermal-natural-convection">Thermal natural convection</a>; reproducible bundle (<code>.krk</code> + CSV + plot script) forthcoming</td></tr><tr><td style="text-align:right;"><strong>Geometry / STL — 3D sphere drag</strong> (D3Q19 + LI-BB cut-link)</td><td style="text-align:right;">Clift, Grace &amp; Weber (1978), free-stream <code>C_d ≈ 2.61</code> at Re = 20</td><td style="text-align:right;">none (no RheoTool unbounded-sphere case); blockage extrapolation <code>D/W → 0</code> is the internal cross-check</td><td style="text-align:right;">≤ 5 % local; resolution-limited geometry gate</td><td style="text-align:right;"><strong>+8.9 %</strong> — extrapolated free-stream <code>C_d ≈ 2.84</code> vs Clift 2.61 (quadratic LSQ, R² = 0.9998); residual is finite lattice resolution</td><td style="text-align:right;"><a href="./sphere-drag-3d">Sphere drag 3D</a>; CSV <code>bench/geometry_stl/sphere_drag_conv*.csv</code></td></tr><tr><td style="text-align:right;"><strong>AMR — conservative-tree (route-native D)</strong></td><td style="text-align:right;">analytic mass conservation (zero net flux ⇒ roundoff drift)</td><td style="text-align:right;">dense-leaf &quot;oracle&quot; Cartesian reference at finest leaf-equivalent resolution</td><td style="text-align:right;">mass drift at roundoff (&lt; 1e-12); route-native obstacle Cd vs oracle</td><td style="text-align:right;"><strong>PASS (conservation)</strong> — relative mass drift <strong>~1.7e-13</strong> (square/cylinder), all obstacle rows &lt; 1e-12 (worst 2.08e-12). Cylinder Cd vs the dense-leaf oracle depends on patch placement: with an <strong>interface-buffered</strong> patch (interfaces moved off the boundary layer) route-native Cd is <strong>1.06× / 1.05× the oracle</strong> at scale 1 / 2; with a <strong>compact patch</strong> cutting through the near-wall region the gap is large (route-native / oracle Cd ≈ <strong>3.2×–5.6×</strong>). Accuracy on integrated quantities is an <strong>OPEN v0.2.0 item</strong>, not a passing gate — see showcase</td><td style="text-align:right;"><a href="./../../benchmarks/refinement_showcase">Refinement showcase</a>; compact-patch CSVs <code>benchmarks/results/repro/refinement/amr_obstacle_convergence_2d_aqua_conv_20757949.csv</code> (+<code>…20761330.csv</code>); interface-buffered CSV <code>benchmarks/results/repro/refinement/amr_obstacle_convergence_2d_aqua_interface_buffered_20260505.csv</code>; design note <code>docs/design/amr_d_publication_validation.md</code></td></tr><tr><td style="text-align:right;"><strong>Viscoelastic — Oldroyd-B cylinder</strong> (TRT-LBM, halfway BB)</td><td style="text-align:right;">none published at this confinement (Oldroyd-B <code>C_d</code> is solver-dependent)</td><td style="text-align:right;">RheoTool <code>rheoFoam</code> fine-mesh (<code>Cylinder/Oldroyd-BLog</code>), log-conformation</td><td style="text-align:right;">&lt; 1 % on <code>C_d</code> at Wi ≤ 1, R = 50, Re = 1</td><td style="text-align:right;"><strong>PASS</strong> — <code>C_d</code> within <strong>−0.40 % / −0.86 % / −0.96 %</strong> of rheoFoam at Wi = 0.1 / 0.5 / 1.0 (diffusive scaling τ = 0.95, halfway BB); validated only for Wi ≤ 1</td><td style="text-align:right;"><a href="./../tutorials/viscoelastic-cylinder">Viscoelastic cylinder</a></td></tr><tr><td style="text-align:right;"><strong>GPU — single-GPU efficiency</strong> (BGK D2Q9, CUDA F64)</td><td style="text-align:right;">memory-bandwidth roofline (A100-40GB, 1.555 TB/s ⇒ 5115 MLUPS ceiling)</td><td style="text-align:right;">Palabos single-GPU F64 D3Q19 TRT (4656 MLUPS, published)</td><td style="text-align:right;">≥ 0.5 of roofline</td><td style="text-align:right;"><strong>PASS</strong> — <strong>3461 MLUPS</strong> at N = 2048 ⇒ <strong>0.68</strong> of A100-40GB roofline, <strong>0.74</strong> of the Palabos number (0.52 even vs the stricter 80 GB ceiling)</td><td style="text-align:right;"><a href="./gpu-certification">GPU certification</a>; CSV <code>benchmarks/results/certification_a100.csv</code></td></tr></tbody></table><h2 id="Notes" tabindex="-1">Notes <a class="header-anchor" href="#Notes" aria-label="Permalink to &quot;Notes {#Notes}&quot;">​</a></h2><ul><li><p><strong>Follow the artifact link</strong> for the full error-norm tables, methodology, mesh/backend details and caveats — the matrix carries only the headline metric.</p></li><li><p><strong>3D rows carry larger residuals</strong> and are documented as resolution-limited on their pages (sphere drag +8.9 %). 3D natural convection is wired (<code>natural_convection_3d</code> preset) but only smoke-validated; a quantitative 3D thermal benchmark is a future item. The 2D rows are the strict acceptance gates.</p></li><li><p><strong>AMR conservation ≠ AMR accuracy.</strong> Mass conservation is exact to roundoff across all shipped CSVs. Integrated-quantity accuracy is <em>not</em> yet a passing gate: the cylinder <code>C_d</code> gap vs the dense-leaf oracle is small only when the coarse/fine interface is buffered off the boundary layer (~1.06×, interface-buffered CSV), and is large for a compact patch cutting the near-wall region (≈3.2–5.6×, the shipped <code>…_conv_*</code> CSVs). This near-interface transport gap is the open item motivating the subcycling integration tracked for the next release. Separately, a bit-exact full-domain refined-patch ↔ dense-leaf parity (<code>L2 = L∞ &lt; 1e-14</code>) is demonstrated for the <strong>3D Poiseuille</strong> route-native canary (<code>test/test_conservative_tree_streaming_3d.jl</code>), establishing that the refined path <em>reproduces</em> the leaf solution when the whole domain is refined; it is not a 2D-cylinder accuracy result.</p></li><li><p><strong>Literal reference-solver backfill.</strong> The Newtonian cavity row ships a complete <code>benchmarks/results/rheotool_compare/newtonian/</code> bundle (both-solver CSVs, per-Re error norms, the <code>.krk</code>, and a self-contained <code>plot.py</code>). The thermal and viscoelastic literal bundles are the next legs of the same backfill.</p></li></ul>',7)])])}const u=t(n,[["render",i]]);export{f as __pageData,u as default};
